import Foundation

/// One entry in the category tree. Leaves have no children.
struct Node: Codable, Hashable {
    let name: String
    let children: [Node]?
}

/// The fixed list everything is picked from. Nothing here is generated by AI at run time.
enum Deck {
    static let categories: [Node] = {
        guard let url = Bundle.main.url(forResource: "categories", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let nodes = try? JSONDecoder().decode([Node].self, from: data) else { return [] }
        return nodes
    }()

    static let allLeaves: [String] = {
        func walk(_ n: Node) -> [String] { n.children.map { $0.flatMap(walk) } ?? [n.name] }
        return categories.flatMap(walk)
    }()

    // randomElement() draws from SystemRandomNumberGenerator, the operating system's
    // secure generator on iOS, and is unbiased, so every option has an equal chance.

    static func descend(_ path: [Node], steps: Int) -> [Node] {
        var p = path
        for _ in 0..<steps {
            guard let kids = p.last?.children, let next = kids.randomElement() else { break }
            p.append(next)
        }
        return p
    }
}

struct Slot: Identifiable, Equatable {
    let id = UUID()
    var path: [Node] = []
    var lock: String? = nil
    var shown: String = ""        // what the square displays, including mid-spin flicker
    var spinning = false

    var canGoDeeper: Bool { path.last?.children != nil }
    var caption: String { path.dropLast().map(\.name).joined(separator: " · ") }
}
